  id String @id @db.Uuid

  /// The seller who owns this session. {@link shopping_mall_sellers.id}
  shopping_mall_seller_id String @db.Uuid

  /// The login session through which this session was created. {@link
  /// shopping_mall_seller_sessions.id}
  shopping_mall_seller_session_id String @db.Uuid

  /// IP address of the client that created this session
  ip String

  /// URL that referred the client to create this session
  referrer String?

  /// The full URL where the session was created
  href String

  /// When this session was created
  created_at DateTime @db.Timestamptz

  /// When this session expires and becomes invalid
  expired_at DateTime @db.Timestamptz

