  /// provides a security mechanism against token hijacking or replay attacks.
  expired_at DateTime @db.Timestamptz

  /// When the password reset record was initially created. This timestamp
  /// helps with auditing and tracking when reset requests were made.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  seller shopping_mall_sellers @relation(fields: [shopping_mall_seller_id], references: [id], onDelete: Cascade, map: "shopping_mall_seller_password_resets_shopping_mall_sel_b4e7cfe0")

  // spellchecker: ignore-next-line
  @@index([shopping_mall_seller_id, expired_at], map: "shopping_mall_seller_password_resets_shopping_mall_sel_2b24e7b3")
}

