  @@index([shopping_mall_admin_id])

  @@index([status])
  @@index([created_at])
  // spellchecker: ignore-next-line
  @@index([shopping_mall_seller_id, created_at], map: "shopping_mall_seller_approvals_shopping_mall_seller_id_1e2b9cca")
}

