  /// all customers.
  email String

  /// Hashed password for customer authentication.
  password String

  /// Customer's display name for public interactions.
  display_name String

  /// Customer's phone number for communication and delivery purposes.
  phone_number String

  /// Timestamp when the customer account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the customer account was last updated.
  updated_at DateTime @db.Timestamptz

