  analytics                    shopping_mall_seller_analytics[]
  sellerOrderItems             shopping_mall_seller_order_items[]
  inventoryAlerts              shopping_mall_seller_inventory_alerts[]
  sanctions                    shopping_mall_user_sanctions[]
